INSERT INTO public.noticias (id, link, fonte, "tag", empresa, titulo, resumo, corpo, publicado_em, criado_em) VALUES (1, 'https://huggingface.co/blog/allenai/toyblocks', 'huggingface.co', 'Pesquisa', 'Geral', 'ToyBlocks: ambiente controlado para aprendizado e avaliação de robôs', 'O ToyBlocks apresenta um mundo controlado desenvolvido para o aprendizado e avaliação em robótica. O projeto serve como base para pesquisas e testes nessa área.', null, '2026-11-06 14:00:48+00', '2026-11-08 14:32:58.200945+00'), (2, 'https://openai.com/index/partnering-with-hacktron', 'openai.com', 'Segurança', 'OpenAI', 'OpenAI e Hacktron fecham parceria para identificar vulnerabilidades', 'A OpenAI formou uma parceria com a Hacktron para encontrar vulnerabilidades e testar conexões com serviços de terceiros. A união busca reforçar as defesas dos sistemas utilizando inteligência artificial de ponta.', null, '2026-11-06 08:00:00+00', '2026-11-08 14:32:58.200945+00'), (3, 'https://openai.com/index/measuring-how-ai-agents-handle-wet-lab-science', 'openai.com', 'Pesquisa', 'OpenAI', 'OpenAI lança BioBasicsBench para avaliar agentes de IA em laboratório', 'A OpenAI apresentou o BioBasicsBench, um benchmark de 100 tarefas voltado à ciência de bancada cotidiana. A ferramenta mede a capacidade de agentes de IA interpretarem dados experimentais brutos.', null, '2026-11-06 00:00:00+00', '2026-11-08 14:32:58.200945+00'), (4, 'https://huggingface.co/blog/open-asr-leaderboard-liva', 'huggingface.co', 'Código aberto', 'Geral', 'Open ASR Leaderboard adiciona variantes de inglês do Egito e Nigéria', 'O Open ASR Leaderboard passou a incluir o inglês egípcio e o inglês nigeriano. A iniciativa expande a avaliação aberta para diferentes sotaques e variações do idioma.', null, '2026-11-06 00:00:00+00', '2026-11-08 14:32:58.200945+00'), (5, 'https://openai.com/index/cultfit-builds-with-codex', 'openai.com', 'Produtos', 'OpenAI', 'Cult.fit adota OpenAI Codex para criar ferramentas e otimizar rotinas', 'A Cult.fit está utilizando o Codex para ajudar equipes de diferentes funções a desenvolver ferramentas próprias. O objetivo é acelerar processos e transformar a execução das atividades internas.', null, '2026-11-05 20:00:00+00', '2026-11-08 14:32:58.200945+00'), (6, 'https://huggingface.co/blog/nvidia/cosmos-interactive-world-simulation', 'huggingface.co', 'Código aberto', 'Geral', 'NVIDIA lança modelos abertos Cosmos 3 para simulação interativa', 'A NVIDIA disponibilizou os novos modelos abertos Cosmos 3. O projeto tem como foco o avanço da simulação interativa de mundos virtuais.', null, '2026-11-05 19:35:16+00', '2026-11-08 14:32:58.200945+00'), (7, 'https://deepmind.google/blog/gemini-omni-12-flash-fast-and-cost-effective-with-longer-clips/', 'deepmind.google', 'Modelos', 'Google', 'Google anuncia Gemini Omni 1.2 Flash focado em clipes mais longos', 'O modelo Gemini Omni 1.2 Flash foi desenvolvido para oferecer rapidez e eficiência de custos. A versão destaca-se pelo suporte a clipes com maior duração.', null, '2026-11-05 17:05:16+00', '2026-11-08 14:32:58.200945+00'), (8, 'https://openai.com/index/australian-universities-ai-native-graduates', 'openai.com', 'Produtos', 'OpenAI', 'Universidades australianas usam ChatGPT para formar alunos para mercado', 'Instituições de ensino superior da Austrália estão ampliando o acesso ao ChatGPT em seus programas educacionais. A integração da IA nas salas de aula visa capacitar estudantes para um mercado de trabalho voltado à tecnologia.', null, '2026-11-05 17:00:00+00', '2026-11-08 14:32:58.200945+00'), (9, 'https://blog.google/innovation-and-ai/technology/developers-tools/introducing-gemini-omni-1-2-flash/', 'blog.google', 'Multimodal', 'Google', 'Gemini Omni 1.2 Flash traz geração de vídeo nativa e custo menor', 'O Gemini Omni 1.2 Flash introduz a geração e edição nativas de vídeos de 15 segundos com maior consistência. Além disso, o modelo é disponibilizado com preços 30% menores.', null, '2026-11-05 17:00:00+00', '2026-11-08 14:32:58.200945+00'), (10, 'https://openai.com/index/introducing-gpt-6-cyber', 'openai.com', 'Segurança', 'OpenAI', 'OpenAI apresenta GPT-6 Cyber voltado a defesas de cibersegurança', 'A OpenAI lançou o GPT-6 Cyber, um modelo focado em segurança cibernética para encontrar vulnerabilidades exploráveis e criar correções. O sistema foi projetado e treinado para atuar estritamente dentro do escopo autorizado.', null, '2026-11-05 09:00:00+00', '2026-11-08 14:32:58.200945+00'), (11, 'https://openai.com/index/merge-builds-with-openai', 'openai.com', 'Produtos', 'OpenAI', 'Merge utiliza tecnologias da OpenAI no desenvolvimento de ferramentas', 'A Merge aplica o GPT-6 Astra, o ChatGPT e o Codex para revisar código de produtos e oferecer suporte ao marketing. A empresa também utiliza a IA para organizar jantares executivos e preparar atualizações comerciais.', null, '2026-11-05 08:00:00+00', '2026-11-08 14:32:58.200945+00'), (12, 'https://openai.com/index/setting-new-standard-responsible-ai-infrastructure', 'openai.com', 'Regulação', 'OpenAI', 'OpenAI estabelece diretrizes para infraestrutura responsável de IA', 'A OpenAI introduziu o National Community Compact e o Compute Campus Policy Blueprint. As diretrizes buscam proteger recursos locais, gerar empregos e orientar o desenvolvimento de infraestrutura de inteligência artificial de forma responsável.', null, '2026-11-05 02:00:00+00', '2026-11-08 14:32:58.200945+00');